; Generated by gen-proxy.js: every export jumps to the same export of the system DLL.
; System DLLs that import the proxied DLL may call it before its DllMain has run, so an empty
; slot first resolves the table (EnsureSystemDll).

EXTERN EnsureSystemDll:PROC
EXTERN MissingExport:PROC

.data
PUBLIC ProxyProcs
ProxyProcs QWORD 181 DUP(0)

.code
; r11 = export index. Keeps the argument registers, fills the table, then jumps.
ResolveAndJump PROC
    push rcx
    push rdx
    push r8
    push r9
    sub rsp, 68h
    mov [rsp + 60h], r11
    movdqu [rsp + 20h], xmm0
    movdqu [rsp + 30h], xmm1
    movdqu [rsp + 40h], xmm2
    movdqu [rsp + 50h], xmm3
    call EnsureSystemDll
    movdqu xmm0, [rsp + 20h]
    movdqu xmm1, [rsp + 30h]
    movdqu xmm2, [rsp + 40h]
    movdqu xmm3, [rsp + 50h]
    mov r11, [rsp + 60h]
    add rsp, 68h
    pop r9
    pop r8
    pop rdx
    pop rcx
    lea rax, ProxyProcs
    mov rax, qword ptr [rax + r11 * 8]
    test rax, rax
    jz Missing
    jmp rax
Missing:
    ; The system DLL has no such export (or could not be loaded): say which and stop, instead of
    ; jumping to address 0
    mov rcx, r11
    sub rsp, 28h
    call MissingExport
ResolveAndJump ENDP

